class Solution:
    def minInteger(self, num: str, k: int) -> str:
        from collections import deque
        if k <= 0 or not num:
            return num
        queues = [deque() for _ in range(10)]
        for i, c in enumerate(num):
            queues[int(c)].append(i)
        n = len(num)
        bit = [0] * (n + 1)
        def update(i, val):
            i += 1
            while i <= n:
                bit[i] += val
                i += i & (-i)
        def query(i):
            s = 0
            i += 1
            while i > 0:
                s += bit[i]
                i -= i & (-i)
            return s
        result = []
        used = [False] * n
        for _ in range(n):
            for d in range(10):
                if not queues[d]:
                    continue
                idx = queues[d][0]
                swaps = idx - query(idx)
                if swaps <= k:
                    k -= swaps
                    queues[d].popleft()
                    result.append(str(d))
                    used[idx] = True
                    update(idx, 1)
                    break
        return ''.join(result)

